import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right structure even if empty
    if len(target_state) == 0:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        target_state = target_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Ensure cdc_events has the right structure even if empty
    if len(cdc_events) == 0:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])
        cdc_events = cdc_events.astype({
            "seq": "int64",
            "order_id": "int64",
            "op": "object",
            "status": "object",
            "amount": "float64",
            "event_ts": "datetime64[us]"
        })

    # Step 1: Remove duplicate events (keep first occurrence by seq per order)
    cdc_events = cdc_events.sort_values(by=["order_id", "seq"]).drop_duplicates(
        subset=["order_id", "seq"], keep="first"
    )

    # Create a dictionary of current state for fast lookups
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders have been touched and their final deletion status
    touched_orders = set()
    final_deletions = {}  # order_id -> seq of final 'D' event

    # Sort events by order_id and seq to process in order
    cdc_events = cdc_events.sort_values(by=["order_id", "seq"]).reset_index(drop=True)

    # Apply events in sequence order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Step 2: Replay guard - skip if order exists and seq <= last_seq
        if order_id in state_dict:
            if seq <= state_dict[order_id]["last_seq"]:
                continue

        touched_orders.add(order_id)

        # Step 3: Apply the operation
        if op in ("I", "U"):
            if order_id in state_dict:
                # Update existing row
                # For 'U': if amount is NULL, keep the old amount; otherwise use new amount
                if pd.isna(amount) and op == "U":
                    new_amount = state_dict[order_id]["amount"]
                else:
                    new_amount = amount
                state_dict[order_id] = {
                    "status": status,
                    "amount": new_amount,
                    "last_seq": seq
                }
            else:
                # Create new row
                state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            # Clear any deletion marker for this order since it's been recreated
            if order_id in final_deletions:
                del final_deletions[order_id]

        elif op == "D":
            if order_id in state_dict:
                # Mark for deletion and remove from state
                final_deletions[order_id] = seq
                del state_dict[order_id]
            # If order doesn't exist, 'D' does nothing

    # Step 4: Build new_state from final state_dict
    new_state_rows = []
    for order_id, state in sorted(state_dict.items()):
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Step 5: Build tombstones for orders where last event was 'D'
    tombstone_rows = []
    for order_id, deleted_seq in sorted(final_deletions.items()):
        tombstone_rows.append({
            "order_id": order_id,
            "deleted_seq": deleted_seq
        })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
